use bhoo::android_expandable_list::{ExpandableListState as S,ExpandableGroup as G,ExpandableChild as C,FlatPosition as P};
fn group(id:u64,count:usize)->G{G{id,label:format!("Group {id}"),children:(0..count).map(|i|C{id:i as u64,label:format!("Child {i}"),selectable:true}).collect()}}
#[test] fn positions_round_trip_through_expansion(){let mut s=S::default();s.set_groups(vec![group(1,2),group(2,0),group(3,3)]).unwrap();assert!(s.expand(0));assert!(s.expand(2));let expected=[P::Group(0),P::Child{group:0,child:0},P::Child{group:0,child:1},P::Group(1),P::Group(2),P::Child{group:2,child:0},P::Child{group:2,child:1},P::Child{group:2,child:2}];assert_eq!(s.visible_count(),expected.len());for (i,p) in expected.into_iter().enumerate(){assert_eq!(s.position_at(i),Some(p));assert_eq!(s.flat_index(p),Some(i));}assert!(s.collapse(0));assert_eq!(s.position_at(1),Some(P::Group(1)));}
#[test] fn stable_ids_preserve_expansion_and_invalid_data_is_transactional(){let mut s=S::default();s.set_groups(vec![group(11,1),group(22,2)]).unwrap();s.expand(1);s.set_groups(vec![group(22,3),group(11,1)]).unwrap();assert!(s.is_expanded(0));assert_eq!(s.visible_count(),5);assert!(s.set_groups(vec![group(7,1),group(7,2)]).is_err());assert_eq!(s.groups()[0].id,22);}
#[test] fn maximum_expanded_collapses_first_in_adapter_order(){let mut s=S::default();s.set_groups(vec![group(0,1),group(1,1),group(2,1)]).unwrap();s.set_max_expanded(Some(2));s.expand(1);s.expand(0);s.expand(2);assert!(!s.is_expanded(0));assert!(s.is_expanded(1));assert!(s.is_expanded(2));s.set_max_expanded(Some(0));assert!(!s.expand(0));}
#[test] fn handles_large_groups_without_flattened_copy(){let mut s=S::default();s.set_groups((0..10_000).map(|i|group(i,2)).collect()).unwrap();s.expand(9999);assert_eq!(s.position_at(10_001),Some(P::Child{group:9999,child:1}));}
