#[test]
fn programmatic_expansion_scroll_follows_group_after_reorder() {
    use bhoo::*;
    let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();let mut list=S::default();
    list.set_groups(vec![group(1,1),group(2,1),group(3,8)]).unwrap();state.expandable_lists.insert("expandable".into(),list);
    assert!(state.expand_list_group("expandable",2,true));
    let list=state.expandable_lists.get_mut("expandable").unwrap();let mut groups=list.groups().to_vec();groups.swap(1,2);list.set_groups(groups).unwrap();
    let b=Rect{x:0.,y:0.,width:240.,height:144.};
    let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,time|{ui.frame(Input{time,..Input::default()},b,0.,|f|{fixture::LAYOUT.render(f,b,state);});};
    draw(&mut ui,&mut state,1.);draw(&mut ui,&mut state,1.1);draw(&mut ui,&mut state,1.25);
    assert!((state.offsets["expandable"]-50.).abs()<2.0,"scroll should follow the moved group: {}",state.offsets["expandable"]);
    assert!(!state.expand_list_group("expandable",1,false));
    assert!(state.collapse_list_group("expandable",1));
    assert!(!state.collapse_list_group("expandable",1));
}
